COLDWAR_IRQ_apply_industry_debt_accounts.script:
COLDWAR_IRQ_migrate_audit_revision = yes
COLDWAR_IRQ_migrate_direct_rewards_v3 = yes
if = {
	limit = {
		COLDWAR_IRQ_campaign_active = yes
		NOT = { has_country_flag = COLDWAR_IRQ_industry_debt_accounts_implemented }
	}
	if = {
		limit = {
			NOT = { has_country_flag = COLDWAR_IRQ_industry_debt_accounts_quoted }
			check_variable = { gdp_total > 0 }
		}
		set_variable = { COLDWAR_IRQ_industry_debt_accounts_invoice = gdp_total }
		multiply_variable = { COLDWAR_IRQ_industry_debt_accounts_invoice = 0.01 }
		set_country_flag = COLDWAR_IRQ_industry_debt_accounts_quoted
	}
	if = {
		limit = {
			COLDWAR_IRQ_campaign_active = yes
			OR = { has_country_flag = COLDWAR_IRQ_industry_credit_finance_implemented }
			has_country_flag = COLDWAR_IRQ_industry_debt_accounts_quoted
			check_variable = { var = COLDWAR_IRQ_industry_debt_accounts_invoice value = 0 compare = greater_than }
			check_variable = { var = treasury value = COLDWAR_IRQ_industry_debt_accounts_invoice compare = greater_than_or_equals }
			NOT = { has_country_flag = MD_skip_treasury_cost }
		}
		set_temp_variable = { treasury_change = COLDWAR_IRQ_industry_debt_accounts_invoice }
		multiply_temp_variable = { treasury_change = -1 }
		modify_treasury_effect = yes
		set_country_flag = COLDWAR_IRQ_industry_debt_accounts_reward_v3_current
		clr_country_flag = COLDWAR_IRQ_industry_debt_accounts_reward_v3_pending
		set_country_flag = COLDWAR_IRQ_industry_debt_accounts_package_earned
		set_country_flag = COLDWAR_IRQ_industry_debt_accounts_implemented
		clr_country_flag = COLDWAR_IRQ_industry_debt_accounts_pending
		set_country_flag = COLDWAR_IRQ_decision_industry_repay_unlocked
		COLDWAR_IRQ_reconcile_situations = yes
		COLDWAR_IRQ_reconcile_programmes = yes
	}
	else = { set_country_flag = COLDWAR_IRQ_industry_debt_accounts_pending }
}

