			check_variable = { var = treasury value = COLDWAR_IRQ_industry_public_finance_invoice compare = greater_than_or_equals }
			NOT = { has_country_flag = MD_skip_treasury_cost }
		}
		set_temp_variable = { treasury_change = COLDWAR_IRQ_industry_public_finance_invoice }
