COLDWAR_IRQ_refresh_reward_v3_icp_member.script:
if = {
	limit = {
		COLDWAR_IRQ_campaign_active = yes
		has_country_flag = COLDWAR_IRQ_icp_membership_reward_v3_pending
		NOT = { has_country_flag = COLDWAR_IRQ_icp_membership_audit_upgrade_pending }
	}
	if = {
		limit = {
			NOT = { always = no }
		}
		set_country_flag = COLDWAR_IRQ_icp_membership_reward_v3_current
		clr_country_flag = COLDWAR_IRQ_icp_membership_reward_v3_pending
	}
	set_variable = { COLDWAR_IRQ_icp_membership_reward_v3_upgrade_invoice = 0 }
	set_country_flag = COLDWAR_IRQ_icp_membership_reward_v3_upgrade_quoted
}

COLDWAR_IRQ_do_arab_development_offer.script:
if = {
	limit = { COLDWAR_IRQ_campaign_active = yes }
	if = {
		limit = {
			COLDWAR_IRQ_campaign_active = yes
			check_variable = { ruling_party = 18 }
			has_country_flag = COLDWAR_IRQ_decision_arab_development_offer_unlocked
			has_country_flag = COLDWAR_IRQ_arab_joint_planning_implemented
		}
		country_event = { id = COLDWAR_IRQ_decision_events.239 }
	}
}

COLDWAR_IRQ_refresh_reward_v3_bakr_deput.script:
if = {
	limit = {
		COLDWAR_IRQ_campaign_active = yes
		has_country_flag = COLDWAR_IRQ_bakr_deputy_budget_reward_v3_pending
		NOT = { has_country_flag = COLDWAR_IRQ_bakr_deputy_budget_audit_upgrade_pending }
	}
	if = {
		limit = {
			NOT = { has_country_flag = COLDWAR_IRQ_bakr_deputy_budget_reward_v3_upgrade_quoted }
			check_variable = { gdp_total > 0 }
		}
		set_variable = { COLDWAR_IRQ_bakr_deputy_budget_reward_v3_upgrade_invoice = gdp_total }
		if = {
			limit = {
				check_variable = { var = COLDWAR_IRQ_bakr_deputy_budget_audit_pending_quote_gdp value = 0 compare = greater_than }
			}
			set_variable = { COLDWAR_IRQ_bakr_deputy_budget_reward_v3_upgrade_invoice = COLDWAR_IRQ_bakr_deputy_budget_audit_pending_quote_gdp }
		}
		multiply_variable = { COLDWAR_IRQ_bakr_deputy_budget_reward_v3_upgrade_invoice = 0.005 }
		set_country_flag = COLDWAR_IRQ_bakr_deputy_budget_reward_v3_upgrade_quoted
	}
}

